export function confirmPalisadeProclamation(
  state: GameState,
  candidatePath: PalisadePath,
): GameState {
  if (!canProclaimPalisadeEra(state) || state.palisade !== null) return state;
  return projectPalisadeProclamation(state, candidatePath);
}

export function projectPalisadeProclamation(
  state: GameState,
  candidatePath: PalisadePath,
): GameState {
  if (state.era !== 'hamlet' || state.palisade !== null) return state;
  const footprints = palisadeFootprintsForState(state);
  // FIX-15 (WP-1): a ring may take the water as its bound where it runs through it.
  const validation = validatePalisadeCandidate(state, candidatePath, footprints, palisadeCoreFootprintsForState(state), 1, { waterReach: true });
  if (!validation.ok) return state;
  const ring = palisadeRingPoints(validation.candidate.path);
  const water = waterReachSteps(state, ring);
  const reach = water.some(Boolean);
  const gate = chooseGate(state, ring, settlementCenter(footprints), reach ? water : undefined);
  if (gate === null) return state;
  const wallId = wallIdForOrdinal(state.nextConstructionOrdinal);
  const wallSegments = reach ? landRunSegments(ring, gate, water) : orderedSegments(validation.candidate.path, gate);
  const additionalGates = additionalRoadGates(state, validation.candidate.path, gate.point, reach ? wallSegments.map(segment => segment.path) : undefined);
  const sites = createWallSites(wallId, wallSegments, state.tick);

  return {
    ...state,
    era: "palisade",
    eraProclaimedTick: state.tick,
    palisade: {
      id: wallId,
      polygon: validation.candidate.path,
      gate: gate.point,
      ...(additionalGates.length > 0 ? { additionalGates } : {}),
      segments: palisadeSegments(sites),
    },
    constructionSites: [...state.constructionSites, ...sites],
    wallConstructionReserve: snapshotWallConstructionReserve(state, sites, "timber"),
    nextConstructionOrdinal: state.nextConstructionOrdinal + 1,
  };
}

export function expandPalisade(state: GameState, path: PalisadePath): GameState {
  const preview = previewPalisadeExpansion(state, path);
  if (!preview.ok || state.palisade === null) return state;
  const palisade = state.palisade;
  const ring = palisadeRingPoints(preview.path);
  const gateIndex = ring.findIndex(point => point.x === palisade.gate.x && point.y === palisade.gate.y);
  const water = waterReachSteps(state, ring);
  const reach = water.some(Boolean);
  const gate = gateIndex >= 0 ? { point: palisade.gate, stepIndex: gateIndex } : chooseGate(state, ring, settlementCenter(palisadeFootprintsForState(state)), reach ? water : undefined);
  if (gate === null) return state;
  const reusedIds = new Set(preview.reusedSegmentIds);
  const reused = palisade.segments.filter(segment => reusedIds.has(segment.id));
  const removed = palisade.segments.filter(segment => !reusedIds.has(segment.id));
  const reusedKeys = new Set(reused.flatMap(segment => pathStepKeys(segment.edgePath)));
  // The new ring from the gate, in runs of steps not already walled; each run cut into sites of four steps at most.
  const rotated = [...ring.slice(gate.stepIndex), ...ring.slice(0, gate.stepIndex), ring[gate.stepIndex]!];
  const runs: { readonly start: number; readonly points: TileEdgePoint[] }[] = [];
  let current: { start: number; points: TileEdgePoint[] } | null = null;
  for (let index = 1; index < rotated.length; index += 1) {
    const a = rotated[index - 1]!;
    const b = rotated[index]!;
    const fresh = !reusedKeys.has(stepKey(a, b)) && !(reach && isWaterReachStep(state, a, b));
    if (fresh && (current === null || current.points.length - 1 >= PALISADE_SEGMENT_SITE_STEPS)) {
      if (current !== null) runs.push(current);
      current = { start: index - 1, points: [a, b] };
    } else if (fresh && current !== null) current.points.push(b);
    else if (current !== null) { runs.push(current); current = null; }
  }
  if (current !== null) runs.push(current);
  const wallId = palisade.id;
  const ordinal = state.nextConstructionOrdinal;
  const firstOrder = palisade.segments.reduce((max, segment) => Math.max(max, segment.order), -1) + 1;
  const sites = runs.map((run, index) => createPalisadeConstructionSite({
    id: `${wallId}-x${String(ordinal).padStart(6, "0")}-segment-${String(index).padStart(3, "0")}`,
    wallId, segmentIndex: firstOrder + index, gateDistance: Math.min(run.start, ring.length - run.start), order: firstOrder + index,
    path: run.points, startedTick: state.tick,
  }));
  const removedSiteIds = new Set(removed.flatMap(segment => [segment.constructionSiteId, segment.replacementConstructionSiteId]).filter((id): id is string => typeof id === "string"));
  // Sites taken down refund as a cancelled site does (M-rule: 60 % of what was delivered).
  const refund = state.constructionSites.filter(site => removedSiteIds.has(site.id)).reduce((sum, site) => sum + (constructionCancellationRefunds(site).deliveredRefund.timber ?? 0), 0);
  const additionalGates = additionalRoadGates(state, preview.path, gate.point,
    reach ? [...reused.map(segment => segment.edgePath), ...sites.map(site => site.path)] : undefined);
  return {
    ...state,
    treasuryTimber: state.treasuryTimber + refund,
    palisade: {
      id: wallId, polygon: preview.path, gate: gate.point, ...(additionalGates.length > 0 ? { additionalGates } : {}),
      segments: [...reused, ...palisadeSegments(sites)], expansion: { tick: state.tick, arableCells: preview.enclosedArableCells },
    },
    constructionSites: [...state.constructionSites.filter(site => !removedSiteIds.has(site.id)), ...sites],
    wallConstructionReserve: snapshotWallConstructionReserve(state, sites, "timber"),

  return state.era === "hamlet" && marketTownRequirements(state).every((requirement) => requirement.met);
}

/** Opens the optional stone-wall project (K4-1); never available when the scenario turns it off. */
export function canProclaimStoneTownEra(state: GameState): boolean {
  return state.era === "palisade" && stoneWallProjectAvailable(state)
    && stoneWallRequirements(state).every((requirement) => requirement.met)
    && canAffordStoneWallProject(state);
}

export function stoneReplacementSiteId(segmentId: string): string {
  return `${segmentId}-stone`;
}

export function confirmStoneTownProclamation(state: GameState): GameState {
  if (!canProclaimStoneTownEra(state)) return state;
  const replacementSegments = state.palisade?.segments.filter((segment) => segment.completed) ?? [];
  const replacementSites = replacementSegments.map((segment) =>
    createStoneWallConstructionSite({
      id: stoneReplacementSiteId(segment.id),
      wallId: state.palisade?.id ?? "",
      segmentIndex: segment.order,
      gateDistance: segment.gateDistance ?? segment.order,
      order: segment.order,
      path: segment.edgePath,
      startedTick: state.tick,
    }),
  ) ?? [];
  // M-7: the project's cost is spent when it is proclaimed (the B2 prerequisite, now a real payment).
  return {
    ...spendStoneWallProject(state),
    era: "stone_town",
    eraProclaimedTick: state.tick,
    palisade: state.palisade === null
      ? null
      : {
          ...state.palisade,
          segments: state.palisade.segments.map((segment) => ({
            ...segment,
            material: segment.material ?? "timber",
            replacementConstructionSiteId: segment.completed ? stoneReplacementSiteId(segment.id) : null,
          })),
        },
    constructionSites: [...state.constructionSites, ...replacementSites],
    wallConstructionReserve: snapshotWallConstructionReserve(state, replacementSites, "stone"),
  };
}

/** EV-4: a burnt house — level and larder lost, rent-free, no promotion; the household stays. F2-A: the raid burns so too. */
export function burntHouse(house: House, tick: number, eventId: string): House {
  const { promotionTicks: _promotion, ...rest } = house;
  return { ...rest, level: 0, builtLevel: 0, breadStock: 0, unmetRequirementTicks: 0, burntTick: tick, burntByEventId: eventId };
}

export function rebuildSiteFor(state: GameState, buildingId: string): BuildingConstructionSite | null {
  const house = state.houses.find(candidate => candidate.buildingId === buildingId);
  const building = state.buildings.find(candidate => candidate.id === buildingId);
  if (house?.burntTick === undefined || building === undefined) return null;
  if (state.constructionSites.some(site => isBuildingConstructionSite(site) && site.rebuildOf === buildingId)) return null;
  const site = createConstructionSite({ ordinal: state.nextConstructionOrdinal, kind: "house", tx: building.tx, ty: building.ty, startedTick: state.wallTick });
  const left = 1000 - FIRE_CONFIG.rebuildDonePermille;
  const required = Object.fromEntries(Object.entries(site.required).map(([resource, amount]) => [resource, Math.ceil((amount ?? 0) * left / 1000)]));
  return { ...site, required, builderTicks: Math.floor(site.requiredBuilderTicks * FIRE_CONFIG.rebuildDonePermille / 1000), rebuildOf: buildingId };
}

/** EV-6 action `rebuild_house`: starts rebuilding a burnt house (its tiles stay the house's). */
export function rebuildBurntHouse(state: GameState, buildingId: string): GameState {
  const site = rebuildSiteFor(state, buildingId);
  if (site === null) return state;
  return { ...state, constructionSites: [...state.constructionSites, site], nextConstructionOrdinal: state.nextConstructionOrdinal + 1 };
}

/** EV-6: a completed rebuild clears the house's burnt state; its household moves back in at level 0. */
export function completeRebuild(house: House): House {
  const { burntTick: _tick, burntByEventId: _event, ...rest } = house;
  return rest;
}

export function drainagePlan(state: GameState, tx: number, ty: number): DrainagePlan {
  if (stateArchetype(state)?.terrain.kind !== "fen") return { ok: false, reason: "not_fen" };
  const { width, height } = state;
  const still = (x: number, y: number) => x >= 0 && y >= 0 && x < width && y < height
    && state.tiles[y * width + x]!.terrain === "water" && !state.tiles[y * width + x]!.hasRoad && !isFlowingWater(state, y * width + x);
  if (!still(tx, ty) || state.river === undefined) return { ok: false, reason: "not_still_water" };
  const works = state.drainage?.works ?? [];
  if (works.length >= B.maxWorks) return { ok: false, reason: "too_many_works" };
  const taken = new Set(works.flatMap(work => work.cells));
  // The mere's cells joined to the chosen one within the patch.
  const cells: number[] = [];
  const seen = new Set([ty * width + tx]);
  const queue = [ty * width + tx];
  for (let head = 0; head < queue.length; head += 1) {
    const index = queue[head]!;
    cells.push(index);
    const x = index % width, y = Math.floor(index / width);
    for (const [dx, dy] of NEIGHBOURS) {
      const nx = x + dx, ny = y + dy, next = ny * width + nx;
      if (Math.abs(nx - tx) > B.patchRadius || Math.abs(ny - ty) > B.patchRadius || seen.has(next) || !still(nx, ny)) continue;
      seen.add(next);
      queue.push(next);
    }
  }
  if (cells.some(cell => taken.has(cell))) return { ok: false, reason: "busy" };
  const onBank = cells.some(cell => NEIGHBOURS.some(([dx, dy]) => {
    const x = cell % width + dx, y = Math.floor(cell / width) + dy;
    return x >= 0 && y >= 0 && x < width && y < height && state.tiles[y * width + x]!.terrain === "grass";
  }));
  if (!onBank) return { ok: false, reason: "no_bank" };
  const timber = cells.length * B.timberPerCell;
  const have = placementSpendableResource(state, "timber");
  if (have < timber) return { ok: false, reason: "insufficient_timber", timberNeeded: timber, timberHave: have };
  const workNeeded = cells.length * B.workPerCell;
  return { ok: true, cells: cells.sort((a, b) => a - b), timber, workNeeded, seasons: Math.ceil(workNeeded / B.diggers / PRESSURE_BALANCE.seasonTicks) };

export function startDrainage(state: GameState, tx: number, ty: number): GameState {
  const plan = drainagePlan(state, tx, ty);
  if (!plan.ok) return state;
  const drainage = state.drainage ?? { works: [], drained: [] };
  const work: DrainageWork = { id: `drainage-${state.tick}-${tx}-${ty}`, cells: plan.cells, startedTick: state.tick, timber: plan.timber,
    workNeeded: plan.workNeeded, workDone: 0, origin: { tx, ty } };
  return { ...state, ...chargeRoadTimber(state, plan.timber), drainage: { ...drainage, works: [...drainage.works, work] } };
}

/** MA-11 (LB-4, after the field hands): the men each open works takes from what is left, in the works' order. */
export function drainageDiggers(state: Pick<GameState, "drainage">, remaining: number): ReadonlyMap<string, number> {
  const diggers = new Map<string, number>();
  let left = Math.max(0, Math.floor(remaining));
  for (const work of state.drainage?.works ?? []) {
    const men = Math.min(left, B.diggers);
    if (men > 0) diggers.set(work.id, men);
    left -= men;
  }
  return diggers;
}

/** MA-11: one tick of the works — each gains its diggers' work; a finished one turns its cells to meadow. */
export function advanceDrainage(state: GameState, diggers: ReadonlyMap<string, number>): GameState {
  const drainage = state.drainage;
  if (drainage === undefined || drainage.works.length === 0) return state;
  const open: DrainageWork[] = [];
  const finished: DrainageWork[] = [];
  for (const work of drainage.works) {
    const men = diggers.get(work.id) ?? 0;
    const { diggers: _men, ...rest } = work;
    const next: DrainageWork = { ...rest, workDone: Math.min(work.workNeeded, work.workDone + men), ...(men > 0 ? { diggers: men } : {}) };
    (next.workDone >= next.workNeeded ? finished : open).push(next);
  }
  if (finished.length === 0) return { ...state, drainage: { ...drainage, works: open } };
  const dry = new Set(finished.flatMap(work => work.cells));

export function counterOffer(state: GameState, proposer: string, counterpart: string, terms: readonly Term[], key: string):
  { readonly terms: readonly Term[]; readonly changes: readonly TermChange[]; readonly acceptance: Acceptance } | null {
  const greed = hashSeed(state.seed, "negotiation-greed", counterpart.length, key.length) % (GREED_MAX + 1);
  const target = ACCEPT_THETA + COUNTER_MARGIN + greed;
  let draft: Term[] = terms.filter(term => !redLine(state, term));
  let acceptance = evaluateOffer(state, proposer, counterpart, draft);
  for (const kind of COUNTER_DESIRES) {
    if (acceptance.score >= target) break;
    if (kind === "political_support") {
      if (draft.some(term => term.kind === kind)) continue;
      draft = [...draft, { kind, giver: "proposer", years: 2 }];
    } else if (kind === "jointure") {
      // FIX-13 (NG-5b): one jointure, on the first piece the lord holds that can carry it.
      const piece = jointurePiece(state);
      if (draft.some(term => term.kind === kind) || piece === null) continue;
      draft = [...draft, { kind, giver: "proposer", pieceId: piece }];
    } else {
      const per = (MATERIAL_PER_PENNY[kind] ?? 0) * (kind === "pension" ? 5 : 1);
      const material = acceptance.reasons.find(reason => reason.name === "material")?.value ?? 0;
      const room = Math.min(target - acceptance.score, MATERIAL_CAP - material);
      if (room <= 0 || per <= 0) continue;
      const have = amountOf(draft, kind);
      const more = Math.min(Math.ceil(room / per), desireRoom(state, counterpart, kind, draft) - have);
      if (more <= 0) continue;
      const years = kind === "pension" ? 5 : kind === "debt_assumption" ? debtInstalmentYears(state, have + more, debtInstalmentCap(state) - amountOf(draft, "pension")) : undefined;
      if (years === null) continue;
      draft = [...draft.filter(term => !(term.kind === kind && term.giver === "proposer")),
        { kind, giver: "proposer", amount: have + more, ...(years === undefined ? {} : { years }) }];
    }
    acceptance = evaluateOffer(state, proposer, counterpart, draft);
  }
  if (acceptance.score < target) return null;
  return { terms: draft, changes: termChanges(terms, draft), acceptance };
}

export function proposeMarriage(state: GameState, offered: readonly Term[], groomId?: string): GameState {
  if (marriageRefusal(state, offered, groomId) !== null) return state;
  const { groom, bride } = marriageCandidates(state, groomId);
  const terms = withConsent(offered);
  const diplomacy = diplomacyOf(state);
  const ordinal = diplomacy.nextNegotiation;
  const acceptance = evaluateOffer(state, LORD, COUNTERPART, terms);
  const accepted = offerDraw(state, ordinal) < acceptance.permille;
  const counter = accepted ? null : counterOffer(state, LORD, COUNTERPART, terms, `negotiation-${ordinal}`);
  const negotiation: Negotiation = { id: `negotiation-${ordinal}`, proposer: LORD, counterpart: COUNTERPART, purpose: "marriage",
    groomId: groom!.id, brideId: bride!.id, terms, acceptance, status: accepted ? "accepted" : counter === null ? "rejected" : "countered",
    ...(counter === null ? {} : { counter }), tick: state.tick, deadline: state.tick + COUNTER_ANSWER_TICKS };
  const next = withDiplomacy(state, { ...diplomacy, negotiations: [...diplomacy.negotiations, negotiation], nextNegotiation: ordinal + 1 });
  return accepted ? contract(next, negotiation, terms) : next;

const PERSON_PARAMS: Readonly<Record<string, string>> = {
  lordId: "lord", guardianId: "guardian", candidateId: "candidate", heirId: "heir", mayorId: "mayor", leaderId: "leader", predecessorId: "predecessor",
  // LM-E4: the steward of an estate (an estate person).
  stewardId: "steward",
  // FIX-13 (ES-11): a person off the map who died (a neighbour house's, a steward).
  deceasedId: "deceased",
};
export type PersonReader = Partial<Pick<GameState, "persons" | "factions" | "estates">>;
export const namesPerson = (record: Pick<HistoryRecord, "params">) => record.params !== undefined && Object.keys(record.params).some(key => key in PERSON_PARAMS);
const personIndex = new WeakMap<object, { readonly factions: unknown; readonly estates: unknown; readonly byId: Map<string, Person> }>();

/** The town's people (living and past), the factions' and the neighbour estates' — by id (rebuilt when one of them changes). */
function personNamed(state: PersonReader, id: string): Person | undefined {
  const key = state.persons ?? state;
  const factions = state.factions?.people, estates = state.estates?.people;
  let entry = personIndex.get(key);
  if (entry === undefined || entry.factions !== factions || entry.estates !== estates) {
    entry = { factions, estates, byId: new Map([...(estates ?? []), ...(factions ?? []), ...(state.persons?.past ?? []), ...(state.persons?.people ?? [])]
      .map(person => [person.id, person])) };
    personIndex.set(key, entry);
  }
  return entry.byId.get(id);
}

/**
 * FIX-12 (item 4) API: a record's parameters with each person named now — `lordId` gives `lord`, and so on. An id no
 * reader knows keeps the name the record was written with (a save before FIX-12) or the copy's fallback word.
 */
export function historyParams(record: Pick<HistoryRecord, "params">, state?: PersonReader): HistoryParams {
  const params = record.params ?? {};
  if (!namesPerson(record)) return params;
  const named: Record<string, string | number> = { ...params };
  for (const [idKey, nameKey] of Object.entries(PERSON_PARAMS)) {
    const id = params[idKey];
    if (typeof id !== "string") continue;
    const person = state === undefined || id === "" ? undefined : personNamed(state, id);
    named[nameKey] = person !== undefined ? personDisplayName(person) : typeof params[nameKey] === "string" ? params[nameKey] : PERSON_NAME_FALLBACK[nameKey] ?? "";
  }
  return named;
}
